parameters.jsCode:
const urls = $input.first().json.urls;

function getBaseDomain(rawUrl) {
	if (!rawUrl || typeof rawUrl !== "string") return null;

	let url = rawUrl.trim();

	// Remove accidental quotes
	url = url.replace(/^"+|"+$/g, "");

	// Extract protocol + hostname
	const match = url.match(/^(https?:\/\/[^\/?#]+)/i);

	return match ? match[1].toLowerCase() : null;
}

const sourceUrl = $('Product List Scrape Result Webhook').first().json.body.result.url;
const baseUrl = getBaseDomain(sourceUrl);

function normalizeUrl(rawUrl) {
	let url = rawUrl.trim();

	// Remove wrapping quotes
	url = url.replace(/^"+|"+$/g, "");

	// Remove hash fragment
	url = url.replace(/#.*$/, "");

	// Convert relative → absolute
	if (!/^https?:\/\//i.test(url)) {
		if (url.startsWith("/")) {
			url = baseUrl + url;
		} else {
			url = baseUrl + "/" + url;
		}
	}

	// Remove trailing slash except pure domain root
	if (!/^https?:\/\/[^\/]+\/?$/i.test(url)) {
		url = url.replace(/\/+$/, "");
	}

	return url.toLowerCase();
}

$input.first().json.urls = urls.map(url => normalizeUrl(url));
return $input.all()

